//! 🧪️ Genuine take transitions return direct work and preserve the same finite source bank.
use semio_framework_value_retained_clone::*;
use semio_framework_value_derive::{RetainedClone,RetireOwned};
#[derive(Debug,PartialEq,serde::Serialize,RetainedClone,RetireOwned)]
#[value(crate="semio_framework_value_retained_clone")]
enum Choice{Empty,Record{label:String,values:Vec<u64>},Tuple(String,u64)}
use semio_framework_value_testing_allocator::observe_retirement_allocations as heap;
struct Bank{remaining:RetainedCloneGrant}
impl Bank{
 fn new(law:&serde_json::Value)->Self{let s=&law["stock"];Self{remaining:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:s["release"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize}}}
 fn grant(&self,d:RetirementDemand)->RetainedCloneGrant{let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert!(g.maximum_items<=self.remaining.maximum_items&&g.maximum_copy_bytes<=self.remaining.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.remaining.maximum_capacity_bytes&&g.maximum_release_bytes<=self.remaining.maximum_release_bytes&&g.maximum_depth<=self.remaining.maximum_depth);g}
 fn debit(&mut self,work:u64,p:RetainedCloneProgress,h:(usize,usize)){assert!(work<=self.remaining.maximum_items as u64);assert!(p.fits(self.remaining));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));self.remaining.maximum_items-=work as usize;self.remaining.maximum_copy_bytes-=p.copied_bytes;self.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;self.remaining.maximum_release_bytes-=p.released_bytes;}
}
fn round<T:RetainedClone+serde::Serialize+PartialEq+std::fmt::Debug>(value:T,law:&serde_json::Value){
 let expected=serde_json::to_value(&value).unwrap();let mut bank=Bank::new(law);let body=law["body"].as_u64().unwrap()as usize;let limit=law["maximumTurns"].as_u64().unwrap();
 let mut admission=RetainedCloneSource::admission_owned(value,());let mut published=None;for _ in 0..limit{if admission.terminal_is_empty(){break}let g=bank.grant(admission.next_demand().unwrap());let(turn,h)=heap(||if admission.phase()=="ready"{admission.take_output(&mut published,g)}else{admission.advance(g)});let p=match &turn.result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};bank.debit(turn.work,p,h);turn.result.unwrap();}assert!(admission.terminal_is_empty());let mut source=published.expect("same-bank staged source publication");let pointer=source.borrow().get()as*const T;let mut cursor=T::retained_clone_cursor();
 let(turn,h)=heap(||cursor.take(Default::default()));assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap());assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));
 for _ in 0..limit{if cursor.output_ready(){break}let g=bank.grant(cursor.advance_demands(source.borrow(),body).unwrap());let(turn,h)=heap(||cursor.advance(source.borrow(),body,g));let work=turn.work;assert!(work<=g.maximum_items as u64);let p=turn.result.unwrap().progress();bank.debit(work,p,h);assert_eq!(source.borrow().get()as*const T,pointer);assert_eq!(serde_json::to_value(source.borrow().get()).unwrap(),expected);}
 assert!(cursor.output_ready());let d=cursor.take_demand().unwrap();assert_eq!(d.copy_bytes,law["ownershipCopyBytes"].as_u64().unwrap()as usize);let g=bank.grant(d);
 for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,h)=heap(||cursor.take(denied));assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap());assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));assert!(cursor.output_ready());}
 let(turn,h)=heap(||cursor.take(g));let work=turn.work;assert_eq!(work,law["handoffWork"].as_u64().unwrap());let(value,p)=turn.result.unwrap().unwrap();bank.debit(work,p,h);assert_eq!(value,*source.borrow().get());assert_eq!(serde_json::to_value(&value).unwrap(),expected);let(turn,h)=heap(||cursor.take(Default::default()));assert_eq!(turn.work,law["cachedWork"].as_u64().unwrap());assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));
 cursor.begin_close();for _ in 0..limit{if cursor.terminal_is_empty(){break}let g=bank.grant(cursor.close_demands(body).unwrap());let(turn,h)=heap(||cursor.close_step(g));let work=turn.work;bank.debit(work,turn.result.unwrap().progress(),h);}assert!(cursor.terminal_is_empty());
 let mut value=Some(value);let mut close=RetainedCloneClose::default();for _ in 0..limit{if value.is_none()&&close.is_empty(){break}let g=bank.grant(close.next_owner_demands::<T>(value.is_some(),&None,body).unwrap());let(turn,h)=heap(||if close.is_empty(){let turn=close.begin_granted(&mut value,g);RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default())))}}else{close.step_granted(g)});let work=turn.work;bank.debit(work,turn.result.unwrap().progress(),h);}assert!(value.is_none()&&close.is_empty());
 for _ in 0..limit{if source.terminal_is_empty(){break}let g=bank.grant(source.next_close_demand(body).unwrap());let(turn,h)=heap(||source.close_step(g));let work=turn.work;bank.debit(work,turn.result.unwrap().progress(),h);}assert!(source.terminal_is_empty());assert_eq!(heap(||drop((cursor,source,close))).1,(0,0));
}
#[test]
fn original_clone_take_owns_work_quote_denial_cached_and_every_output_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("take.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("take.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let c=&law["cases"];
 round(serde_json::from_value::<u64>(c["scalar"].clone()).unwrap(),&law);round(serde_json::from_value::<String>(c["text"].clone()).unwrap(),&law);round(Some(serde_json::from_value::<String>(c["optional"].clone()).unwrap()),&law);round(serde_json::from_value::<Vec<String>>(c["vector"].clone()).unwrap(),&law);round(serde_json::from_value::<[String;2]>(c["array"].clone()).unwrap(),&law);round(serde_json::from_value::<(String,String)>(c["tuple"].clone()).unwrap(),&law);round(Box::new(serde_json::from_value::<String>(c["boxed"].clone()).unwrap()),&law);
 assert_eq!(c["enumEmpty"],true);round(Choice::Empty,&law);round(Choice::Record{label:serde_json::from_value(c["enumRecord"]["label"].clone()).unwrap(),values:serde_json::from_value(c["enumRecord"]["values"].clone()).unwrap()},&law);round(Choice::Tuple(serde_json::from_value(c["enumTuple"][0].clone()).unwrap(),serde_json::from_value(c["enumTuple"][1].clone()).unwrap()),&law);
}
